return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sq','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Krijon kopje rezervë të skedarëve dhe bazës suaj të të dhënave në WordPress në hapësirën tuaj ruajtëse — Dropbox, Google Drive, Cloudflare R2, Amazon S3 ose çdo bucket të përputhshëm me S3 — i rikthen ato menjëherë, dhe importon kopje rezervë të krijuara nga shtojca të tjera kopjimi dhe migrimi.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Kopje rezervë','Get Pro: schedules, several storages, encryption'=>'Merrni Pro: plane, disa hapësira ruajtjeje, enkriptim','Working…'=>'Po punohet…','Finished'=>'Përfunduar','Failed'=>'Dështoi','Cancelled'=>'Anuluar','Cancel'=>'Anulo','Restore'=>'Rikthe','Delete'=>'Fshije','Delete this backup from your storage? This cannot be undone.'=>'Të fshihet ky kopje rezervë nga hapësira juaj ruajtëse? Ky veprim nuk mund të zhbëhet.','No backups yet. Press “Back up now” to make the first one.'=>'Ende nuk ka kopje rezervë. Shtypni "Krijo kopje rezervë tani" për të krijuar të parën.','Reading your storage…'=>'Po lexohet hapësira juaj e ruajtjes…','a complete backup, as opposed to an incremental oneFull backup'=>'Kopje e plotë rezervë','a backup holding only what changed since an earlier oneIncremental backup'=>'Kopje rezervë rritëse','Encrypted'=>'I koduar','From another site'=>'Nga një faqe tjetër','Database'=>'Bazë të dhënash','Files'=>'Skedarë','Uploading %1$s: %2$s%%'=>'Po ngarkohet %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Hyni në Dropbox te dritarja që u hap, mandej ngjiteni kodin që ju shfaq Dropbox-i:','Saved.'=>'U ruajt.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Të hiqet ky destinacion nga shtojca? Kopjet rezervë të ruajtura në të nuk fshihen.','Reload the page to see the restored site.'=>'Ringarkojeni faqen që të shihni sajtin e rikthyer.','Storage'=>'Hapësira e ruajtjes','Import & migrate'=>'Importoni & migroni','Settings'=>'Cilësimet','Sections'=>'Seksionet','Google Drive is connected.'=>'Google Drive është i lidhur.','Google Drive could not be connected.'=>'Google Drive nuk mund të lidhej.','Details'=>'Hollësi','Back up now'=>'Krijo kopje rezervë tani','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Kopjet rezervë shkojnë në hapësirën tuaj të ruajtjes, jo në këtë server. Së pari <a href="%s">lidhni hapësirën tuaj të ruajtjes</a>.','What to back up'=>'Çfarë të kopjohet rezervë','Files and database'=>'Skedarët dhe baza e të dhënave','Database only'=>'Vetëm baza e të dhënave','Files only'=>'Vetëm skedarët','Note (optional)'=>'Shënim (opsionale)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Çdo pjesë ngarkohet në hapësirën tuaj ruajtëse dhe hiqet nga ky server përpara se të krijohet tjetra, kështu që kopja rezervë nuk zë kurrë vend në pritjen tuaj.','Your backups'=>'Kopjet tuaja rezervë','Refresh'=>'Rifresko','Restore this backup'=>'Rikthejeni këtë kopje rezervë','Passphrase'=>'Frazëkalim','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'E kuptoj se kjo zëvendëson skedarët dhe bazën e të dhënave të kësaj faqeje me ato të kopjes rezervë. Skedarët që nuk janë në kopjen rezervë ruhen.','Recent activity'=>'Veprimtaria së fundmi','Backup'=>'Kopje rezervë','Restore / import'=>'Rikthe / importo','Running'=>'Në ekzekutim','Your storage'=>'Hapësira juaj ruajtëse' . "\0" . 'Destinacionet tuaja të ruajtjes','No storage yet. Choose where your backups go below.'=>'Ende nuk ka hapësirë ruajtëse. Zgjidhni më poshtë se ku do të shkojnë kopjet tuaja rezervë.','Ready'=>'Gati','Not connected'=>'I palidhur','Connect'=>'Lidhu','Test'=>'Testo','Edit'=>'Përpunoni','Remove'=>'Hiq','Add storage'=>'Shtoni hapësirë ruajtëse','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Kopjet rezervë shkojnë në një destinacion të vetëm depozitimi. Për të përdorur një tjetër, modifikoni ose hiqni atë më sipër.','Kind of storage'=>'Lloji i hapësirës ruajtëse','Name (for you)'=>'Emri (për ju)','Provider'=>'Ofruesi','Cloudflare account id'=>'ID llogarie Cloudflare','Endpoint address'=>'Adresa e pikës përfundimtare','Region'=>'Rajoni','Bucket'=>'Kovë','Access key id'=>'ID-ja e çelësit të hyrjes','Secret access key'=>'Çelës sekret aksesi','Leave empty to keep the saved key'=>'Lëreni bosh për të mbajtur çelësin e ruajtur','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Për Cloudflare R2: në panelin e Cloudflare hapni R2, krijoni një bucket, më pas “Manage R2 API tokens” → krijoni një token me leje Object Read & Write për atë bucket, dhe kopjoni këtu ID-në e çelësit të hyrjes (access key id) dhe sekretin.','Dropbox app key'=>'Çelësi i aplikacionit Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Krijoni një aplikacion te dropbox.com/developers/apps (Scoped access, App folder) me lejet files.content.read, files.content.write dhe files.metadata.read, dhe kopjoni këtu çelësin e aplikacionit të tij. Ruajeni, pastaj shtypni Lidh.','OAuth client id'=>'ID klienti OAuth','OAuth client secret'=>'Sekreti i klientit OAuth','Leave empty to keep the saved secret'=>'Lëreni bosh për të ruajtur sekretin e ruajtur','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Në Google Cloud Console, aktivizoni Google Drive API, më pas krijoni një klient OAuth të llojit “Web application” me këtë adresë si URI të autorizuar ridrejtimi:','Save, then press Connect. The plugin only sees the files it creates.'=>'Ruajeni, mandej shtypni Lidhu. Shtojca sheh vetëm kartelat që krijon vetë.','Folder inside the storage (optional)'=>'Dosje brenda hapësirës së ruajtjes (opsionale)','Save storage'=>'Kurseni hapësirë ruajtëse','Import a backup from another plugin or host'=>'Importoni një kopje rezervë nga një shtojcë ose pritës tjetër','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Importoni një faqe nga një kopje rezervë e krijuar nga UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, ose çdo arkivë zip/tar e një faqeje WordPress me skedarin e saj .sql dump. Përmbajtja shkon te wp-content dhe baza e të dhënave zëvendëson atë të kësaj faqeje; adresat ndryshohen automatikisht në ato të kësaj faqeje.','Upload from your computer'=>'Ngarkoni nga kompjuteri juaj','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Zgjidhni çdo skedar të kopjes rezervë menjëherë (UpdraftPlus krijon disa). Skedarët e mëdhenj dërgohen në pjesë të vogla, kështu që kufiri i ngarkimit të pritësit tuaj nuk zbatohet.','Or from links (Google Drive, Dropbox or any download address)'=>'Ose nga lidhje (Google Drive, Dropbox ose çfarëdo adrese shkarkimi)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Një lidhje për rresht. Për Google Drive dhe Dropbox, ndajeni skedarin me "këdo që ka lidhjen" dhe ngjiteni atë lidhje; çaktivizojeni sërish ndarjen më pas.','Or a file already on this server'=>'Ose një skedar tashmë në këtë server','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Ngarkoni arkivat përmes FTP-së ose përgjegjësit të kartelave të strehuesit tuaj te %s dhe ringarkojeni këtë faqe.','Or a deploy code from another site'=>'Ose një kod shpërndarjeje nga një sajt tjetër','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Nëse një faqe tjetër ju dha një kod shpërndarjeje të Zinn® Backups, ngjiteni këtu për ta kopjuar atë kopje rezervë në këtë faqe pa ndarë çelësat e saj të ruajtjes. Një kod funksionon për disa orë; trajtojeni atë si një fjalëkalim.','Passphrase (only if that backup is encrypted)'=>'Frazëkalim (vetëm nëse ajo kopje rezervë është e koduar)','Import'=>'Importo','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'E kuptoj që importimi zëvendëson përmbajtjen dhe bazën e të dhënave të kësaj faqeje. Pas kësaj, hyni me një llogari nga faqja e importuar.','Moving to Zinn® hosting?'=>'Po kaloni te hostimi Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® mund ta transferojë faqen tuaj nga host-i juaj i vjetër. Nëse host-i juaj i vjetër nuk ju jep qasje në FTP, SSH apo panel kontrolli, instaloni Zinn® Migrate në faqen e vjetër; ai krijon një arkivë të vetme të cilën mund ta importoni këtu ose t\'ia dorëzoni Zinn®.','What goes into a backup'=>'Çfarë përfshihet në një kopje rezervë','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Përfshini kartelat vetjake të WordPress-it (wp-admin, wp-includes). Zakonisht s’është e nevojshme: WordPress-i mund të riinstalohet përherë.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Gjithashtu lini jashtë këto dosje ose skedarë (një për rresht, në lidhje me dosjen e WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Përjashtohen gjithmonë: fshehtinat, hapësira e përkohshme e përditësimit dhe dosjet vetiake të arkivave të shtojcave të tjera të kopjeve rezervë:','Size of each part (MB)'=>'Madhësia e secilës pjesë (MB)','Save settings'=>'Ruaji rregullimet','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Një pjesë e kopjes rezervë nuk mund të hapej për shkrim. Kontrolloni nëse wp-content ka hapësirë të lirë.','A backup part could not be written. Check that wp-content has free space.'=>'Një pjesë e kopjes rezervë nuk mund të shkruhej. Kontrolloni nëse wp-content ka hapësirë të lirë.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Lidhni së pari një destinacion ruajtjeje te skeda Storage: kopjet rezervë ruhen në hapësirën tuaj, jo në këtë server.','Multisite networks are not supported yet.'=>'Rrjetet me shumë faqe (multisite) nuk mbështeten ende.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'PHP-ja e këtij serveri nuk ka shtojcën ZipArchive. Kërkojini presuesit tuaj ta aktivizojë atë.','Starting'=>'Po niset','Listing files'=>'Po listohen skedarët','Backing up the database'=>'Po krijohet kopje rezervë e bazës së të dhënave','Packing files'=>'Duke paketuar skedarët','Uploading to your storage'=>'Po ngarkohet te hapësira juaj e ruajtjes','Finishing'=>'Po përfundon','The backup reached an unknown stage.'=>'Kopja rezervë arriti një fazë të panjohur.','Backup %s started.'=>'Kopjimi rezervë i %s filloi.','Found %1$s files (%2$s).'=>'U gjetën %1$s skedarë (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Baza e të dhënave: %1$d tabela, %2$s rreshta, %3$s e ngjeshur.','Backup complete: %1$s stored in %2$d destination.'=>'Kopja rezervë përfundoi: %1$s u ruajt në %2$d destinacion.' . "\0" . 'Rezervimi përfundoi: %1$s u ruajt në %2$d destinacione.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Disa pjesë të ngarkuara tashmë nuk mund të hiqeshin nga hapësira juaj e ruajtjes; ato ndodhen në një dosje kopjimi rezervë të paplotë dhe nuk ofrohen kurrë për rikthim.','A storage destination was removed while the backup was running.'=>'Një vendmbërritje depozitimi u hoq ndërkohë që kopja rezervë po ekzekutohej.','That is not a backup folder.'=>'Ajo nuk është dosje kopjeje rezervë.','That storage destination is no longer saved on this site.'=>'Ky destinacion depozitimi nuk është më i ruajtur në këtë faqe.','Later incremental backups are built on this one. Delete those first.'=>'Kopjet e mëvonshme shtuese rezervë janë të bazuara në këtë. Fshijini ato më parë.','This file is not an encrypted Zinn® Backups file.'=>'Ky skedar nuk është një skedar i koduar Zinn® Backups.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Kopja rezervë nuk mund të deshifrohej: fraza e kalimit është e pasaktë ose skedari është i dëmtuar.','The encrypted backup file is incomplete.'=>'Skedari i kopjes rezervë të koduar nuk është i plotë.','The database file could not be written. Check that wp-content has free space.'=>'Skedari i bazës së të dhënave nuk mund të shkruhej. Kontrolloni që wp-content të ketë hapësirë të lirë.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Ky nuk është një kod shpërndarjeje. Një kod shpërndarjeje fillon me zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Ai kod instalimi është i dëmtuar. Kopjojeni përsëri nga sajti tjetër.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Kodi i vendosjes ka skaduar ose kopja rezervë e tij është fshirë. Krijoni një kod të ri në sajtin tjetër.','That deploy code does not point at a Zinn® Backups backup.'=>'Ky kod vendosjeje nuk tregon një kopje rezervë të Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Kodi i vendosjes ka skaduar. Krijoni një kod të ri në faqen tjetër.','The server stopped honouring partial downloads. Start the import again.'=>'Shërbyesi nuk pranon më shkarkime të pjesshme. Ju lutemi, rifilloni importimin.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Lidhja hapi një faqe uebi në vend të një skedari. Për Google Drive dhe Dropbox, ndani skedarin me "këdo që ka lidhjen" dhe ngjiteni atë lidhje.','The link answered with HTTP %d.'=>'Lidhja u përgjigj me HTTP %d.','The file list could not be written.'=>'Lista e skedarëve nuk mund të shkruhej.','The storage service could not be reached: %s'=>'Shërbimi i depozitimit nuk u arrit dot: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s u përgjigj me HTTP %2$d: %3$s','no details given'=>'Nuk janë dhënë hollësi','You are not allowed to manage backups.'=>'Nuk ju lejohet të administroni kopje rezervë.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Caktoni kutinë për të konfirmuar se rikthimi zëvendëson skedarët dhe bazën e të dhënave të këtij sajti.','Save the destination first.'=>'Ruani fillimisht destinacionin.','Connected: a test file was written and removed.'=>'U lidh: një skedar prove u shkrua dhe u hoq.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Vendosni fillimisht çelësin e aplikacionit tuaj Dropbox (shihni hapat pranë formularit).','This kind of storage does not sign in.'=>'Ky lloj ruajtjeje nuk identifikohet.','The sign-in expired. Press Connect again.'=>'Hyrja skadoi. Shtypni sërish Lidhu.','Dropbox is connected.'=>'Dropbox është i lidhur.','Settings saved.'=>'Rregullimet u ruajtën.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Një tjetër kopje rezervë, rikthim ose importim është duke u kryer. Prisni që të përfundojë, ose anulojeni.','The upload was not started properly. Start again.'=>'Ngarkimi nuk filloi siç duhet. Filloni përsëri.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Pjesa nuk mbërriti. Serveri juaj mund të kufizojë madhësitë e ngarkimit; provoni përsëri.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Shënoni kutinë për të konfirmuar se importimi zëvendëson përmbajtjen dhe bazën e të dhënave të kësaj faqeje.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Zgjidhni një arkiv për të importuar: ngarkojeni atë, ngjitni një lidhje ose zgjidhni një nga dosja e importit.','Hosting customer? Get %1$d%% off %2$s'=>'Klient i pritjes? Merrni %1$d%% zbritje në %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Si klient i shërbimit të pritjes Zinn Digital®, ju merrni një kod personal për %d%% zbritje në pagesën tuaj të parë. Rinovimet bëhen me çmimin e zakonshëm.','Get my %d%% code and go to checkout'=>'Merrni kodin tim prej %d%% dhe shkoni te pagesa','Sorry, you are not allowed to do that.'=>'Na vjen keq, nuk ju lejohet ta bëni këtë.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Kjo zbritje është për klientët me një plan pritjeje me pagesë në gjendje të mirë. Provat falas nuk kualifikohen.','You have already used your hosting-customer discount for this plugin.'=>'E keni përdorur tashmë zbritjen tuaj të klientit të pritjes për këtë shtojcë.','We could not get your code just now. Please try again in a few minutes.'=>'Nuk mundëm ta merrnim kodin tuaj tani. Ju lutemi provoni përsëri pas disa minutash.','Reading the backup'=>'Duke lexuar kopjen rezervë','Downloading the archive'=>'Po shkarkohet arkiva','Recognising the archive'=>'Po njihet arkivi','Restoring files'=>'Duke rikthyer skedarët','Downloading the database'=>'Po shkarkohet baza e të dhënave','Restoring the database'=>'Po rikthehet baza e të dhënave','Updating the site address'=>'Po përditësohet adresa e sajtit','Switching to the restored database'=>'Po kalohet te baza e të dhënave e rikthyer','The restore reached an unknown stage.'=>'Rikthimi arriti një fazë të panjohur.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Kjo dosje nuk përmban asnjë kopje rezervë të plotë të Zinn® Backups (manifesti mungon).','This backup is encrypted. Enter its passphrase to restore it.'=>'Kjo kopje rezervë është e koduar. Futni frazëkalimin e saj për ta rikthyer.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Kjo kopje rezervë inkrementale ka nevojë për kopjen rezervë %s, e cila nuk gjendet më në hapësirën e ruajtjes.','Restoring the backup of %1$s (%2$d file parts).'=>'Po rikthehet kopja rezervë e %1$s (%2$d pjesë skedari).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Skedari %1$s nuk mund të mbishkruhej sepse ky sajti nuk lejohet ta ndryshojë atë, dhe u la ashtu siç është: %2$s' . "\0" . '%1$s skedarë nuk mund të mbishkruheshin sepse kjo faqe nuk lejohet t\'i ndryshojë ata, dhe u lanë ashtu siç janë: %2$s','Restored %s files.'=>'U rikthyen %s skedarë.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s nuk përputhej me checksum-in e vet pas shkarkimit. Kopja në ruajtje mund të jetë e dëmtuar.','%s did not arrive. Upload it again.'=>'%s nuk mbërriti. Ju lutemi, ngarkojeni përsëri.','Recognised: %s.'=>'U njoh: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'U importuan %1$s skedarë në wp-content (%2$s u lanë jashtë: fshehtinat, drop-ins dhe dosjet e shtojcave të tjera të kopjeve rezervë).','The archive has no database dump, so only files were imported.'=>'Arkiva nuk përmban ndonjë kopje të bazës së të dhënave, ndaj u importuan vetëm skedarët.','Database restored into %d temporary tables.'=>'Baza e të dhënave u rikthye në %d tabela të përkohshme.','%s has no WordPress tables in it and was skipped.'=>'%s nuk përmban tabela të WordPress-it dhe u kapërcye.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Baza e të dhënave e kopjes rezervë nuk përmban tabela të WordPress-it, ndaj nuk u zëvendësua asgjë.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Kjo kopje rezervë është e një rrjeti me shumë faqe (multisite). Rikthimi i një rrjeti në një faqe të vetme nuk mbështetet.','Moving the content from %1$s to %2$s.'=>'Po zhvendoset përmbajtja nga %1$s te %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Rikthimi përfundoi. Nëse jeni çidentifikuar, identifikohuni me një llogari nga sajti i rikthyer.','Restore complete.'=>'Rikthimi përfundoi.','%1$s — trying again in %2$d seconds.'=>'%1$s — po provohet sërish pas %2$d sekondash.','Cancelled.'=>'U anulua.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Kopjet rezervë shkojnë në një destinacion ruajtjeje. Redaktoni ose hiqni atë që keni për të përdorur një tjetër.','The database file could not be opened.'=>'Skedari i bazës së të dhënave nuk mund të hapej.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Baza e të dhënave refuzoi një deklaratë nga kopja rezervë: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Tabelat e rikthyera nuk mund të ndërroheshin: %s. Sajti juaj mbetet i pandryshuar.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Nuk ka dosje të shkrueshme për skedarët e përkohshëm të kopjeve rezervë. Bëjeni wp-content të shkrueshme dhe provoni përsëri.','Could not create a folder for this job.'=>'Nuk mund të krijohej një dosje për këtë punë.','%s — guides and services'=>'%s — udhëzues dhe shërbime','User guides'=>'Udhëzuesit e përdoruesit','Read the %s user guide'=>'Lexoni udhëzuesin e përdoruesit për %s','Hide this'=>'Fshiheni këtë','Zinn® hosting for WordPress'=>'Pritje Zinn® për WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, kopje rezervë të përditshme, migrim falas dhe një panel kontrolli i krijuar për njerëzit që menaxhojnë më shumë se një faqe.','The Zinn® marketplace'=>'Tregu i Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Blini dhe shisni sajte të konsoliduara, domene dhe vendosje lidhjesh, me paratë e ruajtura të sigurta derisa të dyja palët të jenë të kënaqura.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — punësoni njerëz që e bëjnë këtë si profesion','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Tregu ynë global i profesionistëve të pavarur: shfletoni mbi 10.000 shërbime të gatshme nga shkrimtarë, stilistë, zhvillues dhe ekspertë të SEO-së, ose postoni një projekt dhe lërini të bëjnë oferta.','See the Zinn Digital® release notes.'=>'Shihni shënimet e versionit të Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Shërbimi i përditësimeve të Zinn® nuk lëshoi një lidhje shkarkimi për këtë përditësim. Kontrolloni nëse ky sajti mund të lidhet me platformën Zinn®, pastaj provoni përsëri.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Përditësimi nuk mund të shkarkohej nga shërbimi i përditësimeve Zinn® (%s). Ju lutemi provoni përsëri pas disa minutash.','The downloaded update failed its integrity check and was not installed.'=>'Përditësimi i shkarkuar dështoi në kontrollin e integritetit dhe nuk u instalua.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Arkiva zip nuk mund të hapej. Mund të jetë e dëmtuar ose e paplotë.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Kjo skedar .wpress përdor një format që nuk mund ta lexojmë (mund të jetë ngjeshur ose koduar nga All-in-One WP Migration). Ju lutemi eksportojeni përsëri pa kodim.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Kjo është një skedar Duplicator “DupArchive” (.daf). Te Duplicator, ndërtojeni paketën sërish me formatin e arkivit të caktuar në ZIP, pastaj importojeni atë.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Kjo kopje rezervë e bazës së të dhënave nga UpdraftPlus është e koduar. Çkodojeni atë në UpdraftPlus (ose çaktivizoni kodimin e bazës së të dhënave dhe bëni përsëri një kopje rezervë), pastaj importojeni.','Database dump'=>'Dump i bazës së të dhënave','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s nuk është një arkiv kopjeje rezervë që mund ta lexojmë (zip, tar, tar.gz, .wpress, .sql ose .sql.gz).','Website archive'=>'Arkiva e faqes së internetit','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s nuk përmban përmbajtje të WordPress-it (asnjë dosje wp-content dhe asnjë kopje të bazës së të dhënave).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Ky skedar .wpress është i koduar ose i ngjeshur nga All-in-One WP Migration. Ju lutemi eksportojeni sërish me kodimin dhe ngjeshjen të çaktivizuar, më pas importojeni atë.','Other S3-compatible storage'=>'Hapësirë tjetër ruajtjeje e përputhshme me S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 ose i përputhshëm me S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Çelësat e ruajtjes nuk mund të lexoheshin në këtë faqe. Vendosni përsëri çelësin sekret te skeda Ruajtja.','This kind of storage is not known.'=>'Ky lloj depozitimi nuk njihet.','Choose a kind of storage.'=>'Zgjidhni një lloj hapësire ruajtëse.','Enter the bucket name and the access key.'=>'Futni emrin e bucket-it dhe çelësin e hyrjes.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Futni ID-në e llogarisë suaj Cloudflare (ose pikën fundore të plotë R2).','Enter the endpoint address of your storage.'=>'Futni adresën e pikës fundore të hapësirës suaj të ruajtjes.','Enter the OAuth client id from your Google Cloud project.'=>'Vendosni OAuth client id nga projekti juaj në Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox nuk ktheu një token rifreskimi. Niseni lidhjen sërish.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox nuk është i lidhur. Lidheni sërish te skeda e Hapësirës Ruajtëse.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google nuk ktheu një token rifreskimi. Hiqeni këtë faqe nga aksesi i palëve të treta në llogarinë tuaj Google dhe lidhuni përsëri.','That file is not in Google Drive any more.'=>'Ajo skedar nuk gjendet më në Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive nuk është i lidhur. Lidheni përsëri në skedën Depozitimi.','The storage service did not start the upload.'=>'Shërbimi i ruajtjes nuk e nisi ngarkimin.','The storage service sent a reply that could not be read.'=>'Shërbimi i ruajtjes dërgoi një përgjigje që nuk mund të lexohej.','A temporary backup file could not be read.'=>'Nuk mund të lexohej një kartelë e përkohshme kopjeruajtjeje.','A deploy link is read-only.'=>'Një lidhje shpërndarjeje është vetëm për lexim.','The deploy code has no link for a file this backup needs.'=>'Kodi i vendosjes nuk ka lidhje për një skedar që i nevojitet kësaj kopjeje rezervë.','The deploy link'=>'Lidhja e vendosjes']];